-- Migration 0003: People, Organisations, Affiliations and Tags (ADR 0015, ADR 0018).
--
-- Conventions for every core record table from here on:
--   * id is a prefixed, time-sortable text id generated by @crm/core (per_, org_, aff_, ...).
--   * Timestamps are ISO-8601 UTC text (`2026-11-04T10:00:00.000Z`). Calendar dates are
--     `YYYY-MM-DD` text.
--   * Soft delete: `deleted_at` / `deleted_by`. Live rows have `deleted_at IS NULL`. Trash is the
--     set of soft-deleted rows; a scheduled purge hard-deletes them after 30 days.
--   * `merged_into_id` points a merged-away record at its survivor.
--   * Child rows (emails, phones, domains, addresses) are owned by their parent and replaced
--     wholesale by operations; they are hard-deleted with the parent on purge or erase.
--   * Uniqueness "across live records" uses a denormalised `live` flag on the child row, kept in
--     step with the parent's `deleted_at` by triggers, so a partial unique index can enforce it.
--     Restoring a parent whose email/domain has since been taken fails with a UNIQUE error.

-- People ---------------------------------------------------------------------------------------

CREATE TABLE core_person (
  id TEXT PRIMARY KEY NOT NULL,
  given_name TEXT,
  family_name TEXT,
  display_name TEXT NOT NULL,
  location TEXT,
  timezone TEXT,
  -- JSON array of { network, url, handle? }.
  social_profiles TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(social_profiles)),
  -- R2 object key of the avatar image.
  avatar_key TEXT,
  owner_id TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  -- Rich text, stored as Markdown.
  description TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  deleted_by TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  merged_into_id TEXT REFERENCES core_person (id) ON DELETE SET NULL
);
CREATE INDEX core_person_display_name_idx ON core_person (display_name COLLATE NOCASE, id);
CREATE INDEX core_person_owner_idx ON core_person (owner_id);
CREATE INDEX core_person_deleted_idx ON core_person (deleted_at);

CREATE TABLE core_person_emails (
  id TEXT PRIMARY KEY NOT NULL,
  person_id TEXT NOT NULL REFERENCES core_person (id) ON DELETE CASCADE,
  -- Stored lower-cased and trimmed by the operation layer.
  email TEXT NOT NULL CHECK (email = lower(trim(email)) AND email <> ''),
  label TEXT,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  position INTEGER NOT NULL DEFAULT 0,
  live INTEGER NOT NULL DEFAULT 1 CHECK (live IN (0, 1)),
  created_at TEXT NOT NULL
);
CREATE INDEX core_person_emails_person_idx ON core_person_emails (person_id, position);
CREATE UNIQUE INDEX core_person_emails_live_email_uq ON core_person_emails (email) WHERE live = 1;
CREATE UNIQUE INDEX core_person_emails_primary_uq ON core_person_emails (person_id)
  WHERE is_primary = 1;
CREATE UNIQUE INDEX core_person_emails_person_email_uq ON core_person_emails (person_id, email);

CREATE TABLE core_person_phones (
  id TEXT PRIMARY KEY NOT NULL,
  person_id TEXT NOT NULL REFERENCES core_person (id) ON DELETE CASCADE,
  -- As entered; `number_normalised` holds digits and a leading + for matching.
  number TEXT NOT NULL CHECK (number <> ''),
  number_normalised TEXT NOT NULL,
  label TEXT,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  position INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX core_person_phones_person_idx ON core_person_phones (person_id, position);
CREATE INDEX core_person_phones_number_idx ON core_person_phones (number_normalised);
CREATE UNIQUE INDEX core_person_phones_primary_uq ON core_person_phones (person_id)
  WHERE is_primary = 1;

CREATE TRIGGER core_person_emails_live_on_insert
AFTER INSERT ON core_person_emails
WHEN (SELECT deleted_at FROM core_person WHERE id = NEW.person_id) IS NOT NULL
BEGIN
  UPDATE core_person_emails SET live = 0 WHERE id = NEW.id;
END;

CREATE TRIGGER core_person_emails_live_on_delete
AFTER UPDATE OF deleted_at ON core_person
WHEN (OLD.deleted_at IS NULL) <> (NEW.deleted_at IS NULL)
BEGIN
  UPDATE core_person_emails SET live = (NEW.deleted_at IS NULL) WHERE person_id = NEW.id;
END;

-- Organisations --------------------------------------------------------------------------------

CREATE TABLE core_organisation (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (name <> ''),
  website TEXT,
  industry TEXT,
  parent_id TEXT REFERENCES core_organisation (id) ON DELETE SET NULL CHECK (parent_id <> id),
  -- R2 object key of the logo.
  avatar_key TEXT,
  owner_id TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  -- Rich text, stored as Markdown.
  description TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  deleted_by TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  merged_into_id TEXT REFERENCES core_organisation (id) ON DELETE SET NULL
);
CREATE INDEX core_organisation_name_idx ON core_organisation (name COLLATE NOCASE, id);
CREATE INDEX core_organisation_parent_idx ON core_organisation (parent_id);
CREATE INDEX core_organisation_owner_idx ON core_organisation (owner_id);
CREATE INDEX core_organisation_deleted_idx ON core_organisation (deleted_at);

CREATE TABLE core_organisation_domains (
  id TEXT PRIMARY KEY NOT NULL,
  organisation_id TEXT NOT NULL REFERENCES core_organisation (id) ON DELETE CASCADE,
  -- Bare host, lower-cased, no scheme or `www.` (normalised by the operation layer).
  domain TEXT NOT NULL CHECK (domain = lower(trim(domain)) AND domain <> ''),
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  position INTEGER NOT NULL DEFAULT 0,
  live INTEGER NOT NULL DEFAULT 1 CHECK (live IN (0, 1)),
  created_at TEXT NOT NULL
);
CREATE INDEX core_organisation_domains_org_idx ON core_organisation_domains (organisation_id, position);
CREATE UNIQUE INDEX core_organisation_domains_live_domain_uq ON core_organisation_domains (domain)
  WHERE live = 1;
CREATE UNIQUE INDEX core_organisation_domains_primary_uq ON core_organisation_domains (organisation_id)
  WHERE is_primary = 1;
CREATE UNIQUE INDEX core_organisation_domains_org_domain_uq
  ON core_organisation_domains (organisation_id, domain);

CREATE TRIGGER core_organisation_domains_live_on_insert
AFTER INSERT ON core_organisation_domains
WHEN (SELECT deleted_at FROM core_organisation WHERE id = NEW.organisation_id) IS NOT NULL
BEGIN
  UPDATE core_organisation_domains SET live = 0 WHERE id = NEW.id;
END;

CREATE TRIGGER core_organisation_domains_live_on_delete
AFTER UPDATE OF deleted_at ON core_organisation
WHEN (OLD.deleted_at IS NULL) <> (NEW.deleted_at IS NULL)
BEGIN
  UPDATE core_organisation_domains SET live = (NEW.deleted_at IS NULL)
  WHERE organisation_id = NEW.id;
END;

CREATE TABLE core_organisation_addresses (
  id TEXT PRIMARY KEY NOT NULL,
  organisation_id TEXT NOT NULL REFERENCES core_organisation (id) ON DELETE CASCADE,
  label TEXT,
  line1 TEXT,
  line2 TEXT,
  city TEXT,
  region TEXT,
  postal_code TEXT,
  -- ISO 3166-1 alpha-2 where known.
  country TEXT,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  position INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX core_organisation_addresses_org_idx ON core_organisation_addresses (organisation_id, position);
CREATE UNIQUE INDEX core_organisation_addresses_primary_uq ON core_organisation_addresses (organisation_id)
  WHERE is_primary = 1;

-- Affiliations ---------------------------------------------------------------------------------
-- A Person's link to an Organisation. Ending one and starting another is a job change.

CREATE TABLE core_affiliation (
  id TEXT PRIMARY KEY NOT NULL,
  person_id TEXT NOT NULL REFERENCES core_person (id) ON DELETE CASCADE,
  organisation_id TEXT NOT NULL REFERENCES core_organisation (id) ON DELETE CASCADE,
  -- Job title, e.g. "Head of Sales".
  title TEXT,
  -- Free-text role in the relationship, e.g. "Decision maker".
  role TEXT,
  started_on TEXT,
  ended_on TEXT,
  is_current INTEGER NOT NULL DEFAULT 1 CHECK (is_current IN (0, 1)),
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  created_at TEXT NOT NULL,
  created_by TEXT REFERENCES core_user (id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT,
  deleted_by TEXT REFERENCES core_user (id) ON DELETE SET NULL
);
CREATE INDEX core_affiliation_person_idx ON core_affiliation (person_id);
CREATE INDEX core_affiliation_org_idx ON core_affiliation (organisation_id);
CREATE UNIQUE INDEX core_affiliation_primary_uq ON core_affiliation (person_id)
  WHERE is_primary = 1 AND deleted_at IS NULL;

-- Tags -----------------------------------------------------------------------------------------
-- One org-wide tag vocabulary, applied to any record through a polymorphic link (object type +
-- record id), so extension objects can be tagged later without schema changes.

CREATE TABLE core_tags (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK (name = trim(name) AND name <> ''),
  color TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT REFERENCES core_user (id) ON DELETE SET NULL
);

CREATE TABLE core_record_tags (
  tag_id TEXT NOT NULL REFERENCES core_tags (id) ON DELETE CASCADE,
  object_type TEXT NOT NULL,
  record_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (object_type, record_id, tag_id)
);
CREATE INDEX core_record_tags_tag_idx ON core_record_tags (tag_id, object_type);

-- Hard-deleting a core record (purge or erase) removes its tag links.
CREATE TRIGGER core_person_purge_tags AFTER DELETE ON core_person
BEGIN
  DELETE FROM core_record_tags WHERE object_type = 'person' AND record_id = OLD.id;
END;

CREATE TRIGGER core_organisation_purge_tags AFTER DELETE ON core_organisation
BEGIN
  DELETE FROM core_record_tags WHERE object_type = 'organisation' AND record_id = OLD.id;
END;

UPDATE core_meta SET value = '3' WHERE key = 'schema_version';
